using System;using System.IO;using System.Linq;using System.Windows;using System.Windows.Controls;using System.Windows.Markup;using System.Windows.Media;using AirBridge.Routing;
class PickerTest {
 static string Text(DependencyObject d){string t=d is TextBlock?((TextBlock)d).Text+"|":"";for(int i=0;i<VisualTreeHelper.GetChildrenCount(d);i++)t+=Text(VisualTreeHelper.GetChild(d,i));return t;}
 [STAThread]static int Main(){try{var app=new Application();Window shell;using(var f=File.OpenRead(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"UI","Shell.xaml")))shell=(Window)XamlReader.Load(f);app.Resources=shell.Resources;var picker=new ComboBox{Width=400,Height=36,DisplayMemberPath="Name",ItemsSource=new[]{new ApplicationInput{Id="a:1:1",Name="Browser test · 123",Path="browser.exe"}},SelectedIndex=0};var host=new Window{Width=500,Height=200,Content=picker,ShowInTaskbar=false,Left=-10000,Top=-10000};host.Show();host.UpdateLayout();string text=Text(picker);if(!text.Contains("Browser test · 123")||text.Contains("AirBridge.Routing.ApplicationInput"))throw new Exception("Collapsed selection: "+text);picker.IsDropDownOpen=true;host.UpdateLayout();var item=(ComboBoxItem)picker.ItemContainerGenerator.ContainerFromIndex(0);if(item==null||!Text(item).Contains("Browser test · 123"))throw new Exception("Expanded selection mismatch");picker.IsDropDownOpen=false;host.Close();Console.WriteLine("PASS collapsed/expanded friendly app name using real Shell.xaml template");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
